ReplacementContent:
      {/* Card Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2.5 md:gap-4 items-start">
        {section.id === 'valuation' && <PERatioCard />}
        {sectionCards.map(card => {
          if (card.id === 'pe_ratio') return null; // Prevent double rendering since we hardcoded it above
          return (
            <FundamentalCard
              key={card.id}
              card={card}
              onClick={() => onCardClick(card)}
            />
          );
        })}
      </div>
    </div>
  );
})}

TargetContent:
      {/* Card Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2.5 md:gap-4 items-start">
